window.__finlexDocLoaded(38,{"id":38,"articles":[{"id":1210,"no":"第一条","heading":"","text":"为了规范首次执行企业会计准则对会计要素的确认、计量和财务报表列报，根据《企业会计准则——基本准则》，制定本准则。","seq":0,"links":[{"doc_id":72,"tier":"L3","score":64,"rel_kind":"cites","target_seq":3,"target_art_no":"第四条","dir":"in","note":"正文显式引用《企业会计准则第38号——首次执行企业会计准则》"},{"doc_id":91,"tier":"L3","score":64,"rel_kind":"cites","target_seq":7,"target_art_no":"第8节","dir":"in","note":"正文显式引用《企业会计准则第38号——首次执行企业会计准则》"},{"doc_id":92,"tier":"L3","score":64,"rel_kind":"cites","target_seq":10,"target_art_no":"第11节","dir":"in","note":"正文显式引用《企业会计准则第38号——首次执行企业会计准则》"},{"doc_id":94,"tier":"L3","score":64,"rel_kind":"cites","target_seq":7,"target_art_no":"第8节","dir":"in","note":"正文显式引用《企业会计准则第38号——首次执行企业会计准则》"},{"doc_id":95,"tier":"L3","score":64,"rel_kind":"cites","target_seq":7,"target_art_no":"第8节","dir":"in","note":"正文显式引用《企业会计准则第38号——首次执行企业会计准则》"},{"doc_id":98,"tier":"L3","score":64,"rel_kind":"cites","target_seq":9,"target_art_no":"第10节","dir":"in","note":"正文显式引用《企业会计准则第38号——首次执行企业会计准则》"},{"doc_id":100,"tier":"L3","score":64,"rel_kind":"cites","target_seq":7,"target_art_no":"第8节","dir":"in","note":"正文显式引用《企业会计准则第38号——首次执行企业会计准则》"},{"doc_id":102,"tier":"L3","score":64,"rel_kind":"cites","target_seq":8,"target_art_no":"第9节","dir":"in","note":"正文显式引用《企业会计准则第38号——首次执行企业会计准则》"},{"doc_id":105,"tier":"L3","score":64,"rel_kind":"cites","target_seq":6,"target_art_no":"第7节","dir":"in","note":"正文显式引用《企业会计准则第38号——首次执行企业会计准则》"},{"doc_id":106,"tier":"L3","score":64,"rel_kind":"cites","target_seq":8,"target_art_no":"第9节","dir":"in","note":"正文显式引用《企业会计准则第38号——首次执行企业会计准则》"},{"doc_id":108,"tier":"L3","score":64,"rel_kind":"cites","target_seq":7,"target_art_no":"第8节","dir":"in","note":"正文显式引用《企业会计准则第38号——首次执行企业会计准则》"},{"doc_id":111,"tier":"L3","score":64,"rel_kind":"cites","target_seq":8,"target_art_no":"第9节","dir":"in","note":"正文显式引用《企业会计准则第38号——首次执行企业会计准则》"}]},{"id":1211,"no":"第二条","heading":"","text":"首次执行企业会计准则，是指企业第一次执行企业会计准则体系，包括基本准则、具体准则和会计准则应用指南。","seq":1},{"id":1212,"no":"第三条","heading":"","text":"首次执行企业会计准则后发生的会计政策变更，适用《企业会计准则第28号——会计政策、会计估计变更和差错更正》。","seq":2,"links":[{"doc_id":27,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第28号——会计政策、会计估计变更和差错更正》"}]},{"id":1213,"no":"第四条","heading":"","text":"在首次执行日，企业应当对所有资产、负债和所有者权益按照企业会计准则的规定进行重新分类、确认和计量，并编制期初资产负债表。 编制期初资产负债表时，除按照本准则第五条至第十九条规定要求追溯调整的项目外，其他项目不应追溯调整。","seq":3,"links":[{"doc_id":120,"tier":"L1","score":96,"rel_kind":"companion","target_seq":1,"target_art_no":"第2项","dir":"in","note":"指南详解（第2项·首次执行日采用未来适用法有关项目）：显式指向第4条"}]},{"id":1214,"no":"第五条","heading":"","text":"对于首次执行日的长期股权投资，应当分别下列情况处理： （一）根据《企业会计准则第20号——企业合并》属于同一控制下企业合并产生的长期股权投资，尚未摊销完毕的股权投资差额应全额冲销，并调整留存收益，以冲销股权投资差额后的长期股权投资账面余额作为首次执行日的认定成本。 （二）除上述（一）以外的其他采用权益法核算的长期股权投资，存在股权投资贷方差额的，应冲销贷方差额，调整留存收益，并以冲销贷方差额后的长期股权投资账面余额作为首次执行日的认定成本；存在股权投资借方差额的，应当将长期股权投资的账面余额作为首次执行日的认定成本。","seq":4,"links":[{"doc_id":120,"tier":"L1","score":96,"rel_kind":"companion","target_seq":1,"target_art_no":"第2项","dir":"in","note":"指南详解（第2项·首次执行日采用未来适用法有关项目）：显式指向第5条"},{"doc_id":20,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第20号——企业合并》"}]},{"id":1215,"no":"第六条","heading":"","text":"对于有确凿证据表明可以采用公允价值模式计量的投资性房地产，在首次执行日可以按照公允价值进行计量，并将账面价值与公允价值的差额调整留存收益。","seq":5},{"id":1216,"no":"第七条","heading":"","text":"在首次执行日，对于满足预计负债确认条件且该日之前尚未计入资产成本的弃置费用，应当增加该项资产成本，并确认相应的负债；同时，将应补提的折旧（折耗）调整留存收益。","seq":6},{"id":1217,"no":"第八条","heading":"","text":"对于首次执行日存在的解除与职工的劳动关系计划，满足《企业会计准则第09号——职工薪酬》预计负债确认条件的，应当确认因解除与职工的劳动关系给予补偿而产生的负债，并调整留存收益。","seq":7,"links":[{"doc_id":10,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第09号——职工薪酬》"}]},{"id":1218,"no":"第九条","heading":"","text":"对于企业年金基金在运营中所形成的投资，应当在首次执行日按照公允价值进行计量，并将账面价值与公允价值的差额调整留存收益。","seq":8},{"id":1219,"no":"第十条","heading":"","text":"对于可行权日在首次执行日或之后的股份支付，应当根据《企业会计准则第11号——股份支付》的规定，按照权益工具、其他方服务或承担的以权益工具为基础计算确定的负债的公允价值，将应计入首次执行日之前等待期的成本费用金额调整留存收益，相应增加所有者权益或负债。 首次执行日之前可行权的股份支付，不应追溯调整。","seq":9,"links":[{"doc_id":12,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第11号——股份支付》"}]},{"id":1220,"no":"第十一条","heading":"","text":"在首次执行日，企业应当按照《企业会计准则第13号——或有事项》的规定，将满足预计负债确认条件的重组义务，确认为负债，并调整留存收益。","seq":10,"links":[{"doc_id":14,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第13号——或有事项》"}]},{"id":1221,"no":"第十二条","heading":"","text":"企业应当按照《企业会计准则第18号——所得税》的规定，在首次执行日对资产、负债的账面价值与计税基础不同形成的暂时性差异的所得税影响进行追溯调整，并将影响金额调整留存收益。","seq":11,"links":[{"doc_id":18,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第18号——所得税》"}]},{"id":1222,"no":"第十三条","heading":"","text":"除下列项目外，对于首次执行日之前发生的企业合并不应追溯调整： （一）按照《企业会计准则第20号——企业合并》属于同一控制下企业合并，原已确认商誉的摊余价值应当全额冲销，并调整留存收益。 按照该准则的规定属于非同一控制下企业合并的，应当将商誉在首次执行日的摊余价值作为认定成本，不再进行摊销。 （二）首次执行日之前发生的企业合并，合并合同或协议中约定根据未来事项的发生对合并成本进行调整的，如果首次执行日预计未来事项很可能发生并对合并成本的影响金额能够可靠计量的，应当按照该影响金额调整已确认商誉的账面价值。 （三）企业应当按照《企业会计准则第08号——资产减值》的规定，在首次执行日对商誉进行减值测试，发生减值的，应当以计提减值准备后的金额确认，并调整留存收益。","seq":12,"links":[{"doc_id":230,"tier":"L1","score":94,"rel_kind":"companion","target_seq":0,"target_art_no":"问1","dir":"in","note":"实施问答（问1）：锚定第十三条（条文主题匹配）"},{"doc_id":9,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第08号——资产减值》"},{"doc_id":20,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第20号——企业合并》"}]},{"id":1223,"no":"第十四条","heading":"","text":"在首次执行日，企业应当将所持有的金融资产（不含《企业会计准则第02号——长期股权投资》规范的投资），划分为以公允价值计量且其变动计入当期损益的金融资产、持有至到期投资、贷款和应收款项、可供出售金融资产。 （一）划分为以公允价值计量且其变动计入当期损益或可供出售金融资产的，应当在首次执行日按照公允价值计量，并将账面价值与公允价值的差额调整留存收益。 （二）划分为持有至到期投资、贷款和应收款项的，应当自首次执行日起改按实际利率法，在随后的会计期间采用摊余成本计量。","seq":13,"links":[{"doc_id":3,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第02号——长期股权投资》"}]},{"id":1224,"no":"第十五条","heading":"","text":"对于在首次执行日指定为以公允价值计量且其变动计入当期损益的金融负债，应当在首次执行日按照公允价值计量，并将账面价值与公允价值的差额调整留存收益。","seq":14},{"id":1225,"no":"第十六条","heading":"","text":"对于未在资产负债表内确认、或已按成本计量的衍生金融工具（不包括套期工具），应当在首次执行日按照公允价值计量，同时调整留存收益。","seq":15},{"id":1226,"no":"第十七条","heading":"","text":"对于嵌入衍生金融工具，按照《企业会计准则第22号——金融工具确认和计量》规定应从混合工具分拆的，应当在首次执行日将其从混合工具分拆并单独处理，但嵌入衍生金融工具的公允价值难以合理确定的除外。 对于企业发行的包含负债和权益成份的非衍生金融工具，应当按照《企业会计准则第37号——金融工具列报》的规定，在首次执行日将负债和权益成份分拆，但负债成份的公允价值难以合理确定的除外。","seq":16,"links":[{"doc_id":22,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第22号——金融工具确认和计量》"},{"doc_id":37,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第37号——金融工具列报》"}]},{"id":1227,"no":"第十八条","heading":"","text":"在首次执行日，对于不符合《企业会计准则第24号——套期保值》规定的套期会计方法运用条件的套期保值，应当终止采用原套期会计方法，并按照《企业会计准则第24号——套期保值》处理。","seq":17,"links":[{"doc_id":24,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第24号——套期会计》"}]},{"id":1228,"no":"第十九条","heading":"","text":"发生再保险分出业务的企业，应当在首次执行日按照《企业会计准则第26号——再保险合同》的规定，将应向再保险接受人摊回的相应准备金确认为资产，并调整各项准备金的账面价值。","seq":18},{"id":1229,"no":"第二十条","heading":"","text":"在首次执行日后按照企业会计准则编制的首份年度财务报表（以下简称首份年度财务报表）期间，企业应当按照《企业会计准则第30号——财务报表列报》和《企业会计准则第31号——现金流量表》的规定，编报资产负债表、利润表、现金流量表和所有者权益变动表及附注。 对外提供合并财务报表的，应当遵循《企业会计准则第33号——合并财务报表》的规定。 在首份年度财务报表涵盖的期间内对外提供中期财务报告的，应当遵循《企业会计准则第32号——中期财务报告》的规定。 企业应当在附注中披露首次执行企业会计准则财务报表项目金额的变动情况。","seq":19,"links":[{"doc_id":120,"tier":"L1","score":96,"rel_kind":"companion","target_seq":2,"target_art_no":"第3项","dir":"in","note":"指南详解（第3项·首份中期财务报告和首份年度财务报）：显式指向第20条"},{"doc_id":30,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第30号——财务报表列报（财会〔2026〕11号）》"},{"doc_id":31,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第31号——现金流量表》"},{"doc_id":32,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第32号——中期财务报告》"},{"doc_id":33,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第33号——合并财务报表》"}]},{"id":1230,"no":"第二十一条","heading":"","text":"首份年度财务报表至少应当包括上年度按照企业会计准则列报的比较信息。财务报表项目的列报发生变更的，应当对上年度比较数据按照企业会计准则的列报要求进行调整，但不切实可行的除外。 对于原未纳入合并范围但按照《企业会计准则第33号——合并财务报表》规定应纳入合并范围的子公司，在上年度的比较合并财务报表中，企业应当将该子公司纳入合并范围。对于原已纳入合并范围但按照该准则规定不应纳入合并范围的子公司，在上年度的比较合并财务报表中，企业不应将该子公司纳入合并范围。上年度比较合并财务报表中列示的少数股东权益，应当按照该准则的规定，在所有者权益类列示。 应当列示每股收益的企业，比较财务报表中上年度的每股收益按照《企业会计准则第34号——每股收益》的规定计算和列示。 应当披露分部信息的企业，比较财务报表中上年度关于分部的信息按照《企业会计准则第35号——分部报告》的规定披露。","seq":20,"links":[{"doc_id":33,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第33号——合并财务报表》"},{"doc_id":34,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第34号——每股收益》"},{"doc_id":35,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第35号——分部报告》"}]}]});
